generic='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    yy,xx=q
                    if 0<=yy<h and 0<=xx<w and q not in seen and grid[yy][xx]==color:
                        seen.add(q); stack.append(q)
            minr=min(y for y,x in cells); minc=min(x for y,x in cells)
            shape=frozenset((y-minr,x-minc) for y,x in cells)
            objects.append((color,cells,shape))
    signatures={}
    for color,cells,shape in objects:
        signatures.setdefault(shape,set()).add(color)
    out=[row[:] for row in grid]
    for color,cells,shape in objects:
        others=signatures[shape]-{color}
        if color==1 and others:
            target=sorted(others)[0]
            for r,c in cells: out[r][c]=target
    return out
'''
